<script lang="ts">
  import { goto } from '$app/navigation'; import { page } from '$app/stores'; import { onMount, untrack } from 'svelte'; import type { RunDetail, RunJob } from '@sty/contracts';
  import Archive from 'lucide-svelte/icons/archive'; import CircleAlert from 'lucide-svelte/icons/circle-alert'; import CircleCheck from 'lucide-svelte/icons/circle-check'; import CircleDot from 'lucide-svelte/icons/circle-dot'; import GitBranch from 'lucide-svelte/icons/git-branch'; import RotateCcw from 'lucide-svelte/icons/rotate-ccw'; import Square from 'lucide-svelte/icons/square'; import Terminal from 'lucide-svelte/icons/terminal';
  import { api,apiTextCursor,StyApiError } from '$lib/api'; import type { PageData } from './$types';
  let { data }=$props<{data:PageData}>();const owner=$derived($page.params.owner);const repo=$derived($page.params.repo);const number=$derived(Number($page.params.number));let run=$state<RunDetail>(untrack(()=>data.run));let selected=$state(untrack(()=>data.selected));let logs=$state(untrack(()=>data.logs));let logCursor=$state(untrack(()=>data.logCursor));let loading=$state(false);let actionBusy=$state(false);let error=$state('');
  const job=$derived(run?.jobsDetail.find((item)=>item.id===selected)??run?.jobsDetail[0]??null);
  async function appendLogs(){const current=job;if(!current)return;try{for(let page=0;page<4;page+=1){const next=await apiTextCursor(`/jobs/${current.id}/logs`,logCursor);if(next.text)logs+=next.text;logCursor=next.cursor;if(!next.more)break}}catch{}}
  async function refreshState(){if(!['queued','running'].includes(run.state))return;try{const result=await api<{run:Partial<RunDetail>;jobs:Array<Partial<RunJob>&{id:string}>}>(`/repositories/${owner}/${repo}/runs/${number}/state`);run={...run,...result.run,jobsDetail:run.jobsDetail.map((item)=>({...item,...result.jobs.find((next)=>next.id===item.id)}))};await appendLogs()}catch(cause){error=cause instanceof StyApiError?cause.message:'Run status could not be updated.'}}
  async function choose(id:string){selected=id;logs='';logCursor=-1;await appendLogs()}
  async function action(kind:'cancel'|'retry'){if(actionBusy)return;actionBusy=true;error='';try{const result=await api<{state?:RunDetail['state'];run?:{number:number}}>(`/repositories/${owner}/${repo}/runs/${number}/${kind}`,{method:'POST',body:'{}'});if(kind==='retry'&&result.run)await goto(`/${owner}/${repo}/runs/${result.run.number}`);else if(result.state)run={...run,state:result.state,jobsDetail:run.jobsDetail.map((item)=>['queued','running'].includes(item.state)?{...item,state:'canceled'}:item)}}catch(cause){error=cause instanceof StyApiError?cause.message:`Run could not be ${kind}ed.`}finally{actionBusy=false}}
  $effect(()=>{const id=job?.id;if(!id||typeof window==='undefined')return;const protocol=location.protocol==='https:'?'wss:':'ws:';const socket=new WebSocket(`${protocol}//${location.host}/api/v1/jobs/${id}/live`);socket.binaryType='arraybuffer';socket.onmessage=(event)=>{if(!(event.data instanceof ArrayBuffer)||event.data.byteLength<8)return;const sequence=Number(new DataView(event.data).getBigUint64(0));if(sequence<=logCursor)return;logs+=new TextDecoder().decode(event.data.slice(8));logCursor=sequence};return()=>socket.close()});
  onMount(()=>{
    let timer: ReturnType<typeof setTimeout> | undefined;
    let stopped = false;
    let polling = false;
    const poll = async () => {
      if (polling) return;
      polling = true;
      await refreshState();
      polling = false;
      if (!stopped && ['queued','running'].includes(run.state)) timer = setTimeout(poll, document.hidden ? 10_000 : 2_000);
    };
    const visible = () => { if (!document.hidden && ['queued','running'].includes(run.state)) { clearTimeout(timer); void poll(); } };
    if (['queued','running'].includes(run.state)) timer = setTimeout(poll, 2_000);
    document.addEventListener('visibilitychange', visible);
    return()=>{stopped=true;clearTimeout(timer);document.removeEventListener('visibilitychange',visible)};
  });
</script>
<svelte:head><title>{run?.name??`Run #${number}`} · {owner}/{repo} · Sty</title></svelte:head>
{#if loading}<div class="loading" aria-busy="true"><i></i><i></i></div>{:else if !run}<div class="fatal"><strong>Run unavailable</strong><p>{error}</p></div>{:else}<header class="run-head"><div class="title"><span class="run-icon {run.state}">{#if run.state==='success'}<CircleCheck size={18}/>{:else if run.state==='failure'}<CircleAlert size={18}/>{:else}<CircleDot size={18}/>{/if}</span><div><h1>{run.name}</h1><p>Run #{run.number} · {run.trigger}{run.actor?` by ${run.actor}`:''}</p></div></div><div class="actions">{#if run.state==='queued'||run.state==='running'}<button disabled={actionBusy} onclick={()=>action('cancel')}><Square size={13}/>Cancel</button>{:else}<button disabled={actionBusy} onclick={()=>action('retry')}><RotateCcw size={13}/>Run again</button>{/if}</div></header><div class="run-meta"><span><GitBranch size={12}/>{run.branch}</span><code>{run.commit.slice(0,7)}</code><span>{run.jobs} {run.jobs===1?'job':'jobs'}</span><span class="state-text {run.state}">{run.state}</span></div>{#if error}<p class="notice" role="alert">{error}</p>{/if}<div class="run-layout"><aside><h2>Jobs</h2>{#each run.jobsDetail as item}<button class:active={item.id===job?.id} onclick={()=>choose(item.id)}><span class="job-icon {item.state}">{#if item.state==='success'}<CircleCheck size={15}/>{:else if item.state==='failure'}<CircleAlert size={15}/>{:else}<CircleDot size={15}/>{/if}</span><span><strong>{item.name}</strong><small>{item.runner?.name??(item.state==='queued'?`Waiting for ${item.requiredLabels.join(', ')}`:'No runner')}</small></span></button>{/each}</aside><main>{#if job}<header class="job-head"><div><h2>{job.name}</h2><p>{job.runner?`Ran on ${job.runner.name}`:`Requires ${job.requiredLabels.join(', ')}`}</p></div><span>{job.state}</span></header><section class="terminal"><header><Terminal size={13}/><span>Live log</span><small>{job.logBytes} bytes</small></header><pre>{logs|| (job.state==='queued'?'Waiting for a matching runner…':'No log output.')}</pre></section>{#if job.artifacts.length}<section class="artifacts"><h3>Artifacts</h3>{#each job.artifacts as artifact}<a href="/api/v1/artifacts/{artifact.id}"><Archive size={14}/><span><strong>{artifact.name}</strong><small>{artifact.byteSize} bytes</small></span></a>{/each}</section>{/if}{/if}</main></div>{/if}
<style>
  .loading{display:grid;gap:12px}.loading i{height:80px;background:var(--surface)}.fatal{padding:60px 0;text-align:center}.fatal strong{color:var(--text-strong)}.fatal p{color:var(--text-faint);font-size:10px}.run-head{display:flex;align-items:center;justify-content:space-between;gap:20px;padding-bottom:17px}.title{display:flex;align-items:center;gap:10px}.run-icon{display:grid;width:35px;height:35px;place-items:center;border-radius:8px;background:var(--surface-muted);color:var(--text-faint)}.run-icon.success{background:var(--success-soft);color:var(--success)}.run-icon.failure{background:var(--danger-soft);color:var(--danger)}.run-icon.running,.run-icon.queued{background:var(--brand-soft);color:var(--brand)}h1{margin:0;color:var(--text-strong);font-size:21px;letter-spacing:-.03em}.title p{margin:4px 0 0;color:var(--text-faint);font-size:9px}.actions button{display:inline-flex;height:30px;align-items:center;gap:5px;padding:0 8px;border:1px solid var(--border);border-radius:5px;background:var(--surface);color:var(--text);cursor:pointer;font-size:9px}.run-meta{display:flex;align-items:center;gap:10px;min-height:37px;border-top:1px solid var(--border);border-bottom:1px solid var(--border);color:var(--text-faint);font-size:9px}.run-meta span{display:inline-flex;align-items:center;gap:4px}.run-meta code{color:var(--text-muted)}.state-text{margin-left:auto;text-transform:capitalize}.state-text.success{color:var(--success)}.state-text.failure{color:var(--danger)}.state-text.running,.state-text.queued{color:var(--brand)}.notice{color:var(--danger);font-size:9px}.run-layout{display:grid;grid-template-columns:230px minmax(0,1fr);gap:28px;padding-top:24px}.run-layout>aside{border-right:1px solid var(--border);padding-right:14px}.run-layout aside h2{margin:0 0 8px 4px;color:var(--text-faint);font-size:9px;font-weight:600}.run-layout aside button{display:grid;width:100%;grid-template-columns:22px minmax(0,1fr);align-items:center;gap:7px;padding:8px 6px;border:0;border-radius:5px;background:transparent;color:var(--text);cursor:pointer;text-align:left}.run-layout aside button:hover,.run-layout aside button.active{background:var(--surface-muted)}.job-icon{display:grid;place-items:center;color:var(--text-faint)}.job-icon.success{color:var(--success)}.job-icon.failure{color:var(--danger)}.job-icon.running,.job-icon.queued{color:var(--brand)}.run-layout aside strong,.run-layout aside small{display:block;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.run-layout aside strong{color:var(--text-strong);font-size:10px}.run-layout aside small{margin-top:3px;color:var(--text-faint);font-size:8px}.run-layout>main{min-width:0}.job-head{display:flex;align-items:flex-end;justify-content:space-between;margin-bottom:13px}.job-head h2{margin:0;color:var(--text-strong);font-size:14px}.job-head p{margin:4px 0 0;color:var(--text-faint);font-size:9px}.job-head>span{color:var(--text-muted);font-size:9px;text-transform:capitalize}.terminal{overflow:hidden;border:1px solid var(--border);border-radius:7px;background:#09090a}.terminal>header{display:flex;align-items:center;gap:6px;min-height:34px;padding:0 10px;border-bottom:1px solid #242427;color:#8e8d89;font-size:9px}.terminal header small{margin-left:auto;color:#5f5e5b}.terminal pre{min-height:280px;max-height:540px;overflow:auto;margin:0;padding:13px;color:#d6d4cf;font-family:"SFMono-Regular",Consolas,monospace;font-size:10px;line-height:1.65;white-space:pre-wrap}.artifacts{margin-top:24px}.artifacts h3{margin:0 0 8px;color:var(--text-strong);font-size:11px}.artifacts a{display:grid;grid-template-columns:22px 1fr;align-items:center;gap:7px;padding:9px 3px;border-top:1px solid var(--border-subtle);color:var(--text-muted);text-decoration:none}.artifacts strong,.artifacts small{display:block}.artifacts strong{color:var(--text-strong);font-size:9px}.artifacts small{margin-top:2px;color:var(--text-faint);font-size:8px}@media(max-width:700px){.run-layout{grid-template-columns:1fr}.run-layout>aside{display:flex;overflow-x:auto;border-right:0;border-bottom:1px solid var(--border);padding:0 0 10px}.run-layout aside h2{display:none}.run-layout aside button{min-width:190px}.run-head{align-items:flex-start}.title h1{font-size:18px}.terminal pre{min-height:220px}}
</style>
